def isValidDate(date):
    try:
        month, day, year = [int(x) for x in date.split('/')]
    except:
        return False
    months = [1, 3, 5, 7, 8, 10, 12]
    if month not in months or day < 1 or (month == 2 and (day > 29 or (day == 29 and not isLeapYear(year)))) or (month > 2 and day > 31):
